func (q *Queries) NextTaskNumber(ctx context.Context, projectID string) (int64, error) {
	row := q.db.QueryRowContext(ctx, nextTaskNumber, projectID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

